#[test]
fn q1_ctors_match_class_table() {
    // the 0x002baae8 descriptor of each ctor carries the size the ctor allocates (FUN_001ae4f8(size))
    for &(ctor, size) in CTORS {
        let c = CLASSES.iter().find(|c| c.ctor == ctor).unwrap_or_else(|| panic!("ctor {ctor:#x} not in 0x2baae8"));
        assert_eq!(c.size, size, "ctor {ctor:#x}");
    }
}

#[test]
fn q1_thunks_in_method_table() {
    for &(t, n, callee) in THUNKS {
        let m = by_thunk(t).copied().or_else(|| getter_by_thunk(t).map(|g| g.m)).unwrap_or_else(|| panic!("thunk {t:#x} not bound"));
        if let Some(k) = m.kinds {
            assert_eq!(k.len(), n, "thunk {t:#x} kinds");
        }
        if callee != 0 {
            assert_eq!(m.callee, callee, "thunk {t:#x} callee");
        }
    }
}

#[test]
fn q1_libm_replacements() {
    // run_00246060: sqrtf (0x246060) and the float kernels behind cosf / sinf / atan2f / fmodf / powf are
    // replaced by std f32; spot values the engine relies on
    assert_eq!(4.0f32.sqrt(), 2.0);
    assert!((-1.0f32).sqrt().is_nan());
    assert_eq!((-5.5f32) % 2.0, -1.5); // fmodf keeps the dividend sign
    assert_eq!(2.0f32.powf(10.0), 1024.0);
    assert!((0.0f32.cos() - 1.0).abs() < 1e-7 && 0.0f32.sin() == 0.0);
}
